{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-06",
  "sketch": {
    "components": ["File upload handler", "Public link generator", "File viewer"],
    "dataStores": ["S3 bucket"],
    "externalServices": ["s3"],
    "trustBoundaries": ["Public internet to S3-backed file store", "Anonymous user to uploaded content"],
    "dataClasses": [],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Anyone who guesses or finds the link can view the file forever",
      "scenario": "Because 'Anyone with the link can view the file without logging in' and 'Links never expire', an attacker who obtains a link once (via logs, referrer headers, shared chat, browser history, or brute-forcing a predictable URL) can view the file indefinitely, even long after the uploader intended it to be private or the content is stale.",
      "component": "Public link generator",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "Anyone with the link can view the file without logging in. Links never expire." }
      ],
      "asvs": ["V4.1.3"],
      "cwe": ["CWE-613", "CWE-284"],
      "plainLanguage": "A file link that never expires and needs no login can leak to anyone who ever sees it, forever.",
      "requirement": {
        "title": "Share links must expire and be revocable",
        "given": "a file is shared via a public link",
        "when": "time passes or the uploader wants to stop sharing",
        "then": "the link automatically expires after a bounded period and the uploader can revoke it on demand"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "No authentication means no way to restrict who can view a sensitive file",
      "scenario": "The design states 'Anyone with the link can view the file without logging in.' There is no mechanism to scope access to specific users, so a link leaked via a forwarded email, a shared Slack channel, or a search engine crawl gives full access to whoever has it, with no ability to limit to the intended recipient.",
      "component": "File viewer",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Anyone with the link can view the file without logging in." }
      ],
      "asvs": ["V4.1.1"],
      "cwe": ["CWE-862"],
      "plainLanguage": "There's no login check at all, so the file is really public to anyone with the URL, not just the person it was meant for.",
      "requirement": {
        "title": "Optional access control for shared files",
        "given": "a user shares a file link",
        "when": "the uploader marks the file as restricted",
        "then": "the system requires authentication or a one-time passcode before granting access"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Predictable or enumerable S3-backed links expose other users' files",
      "scenario": "Files are stored in an S3 bucket and served via public links. If link identifiers or S3 object keys are sequential or guessable, an attacker can enumerate URLs to access other users' uploaded documents without ever obtaining a shared link.",
      "component": "S3 bucket",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "Files are stored in an S3 bucket." },
        { "quote": "Anyone with the link can view the file without logging in." }
      ],
      "asvs": ["V8.3.4"],
      "cwe": ["CWE-330", "CWE-639"],
      "plainLanguage": "If the file web address is easy to guess, attackers can scan for other people's private documents.",
      "requirement": {
        "title": "Unguessable share identifiers",
        "given": "a file share link is generated",
        "when": "the link is created",
        "then": "it uses a cryptographically random identifier of sufficient length so it cannot be guessed or enumerated"
      }
    },
    {
      "stride": "Tampering",
      "title": "Unrestricted upload accepts malicious or oversized files",
      "scenario": "The system lets 'Users upload documents' with no stated validation of file type, content, or size. An attacker could upload malware, an HTML/SVG file that executes script when viewed in-browser (stored XSS against anonymous viewers), or an extremely large file to abuse storage/bandwidth.",
      "component": "File upload handler",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "Users upload documents and share them through a public link." }
      ],
      "asvs": ["V12.1.1", "V12.4.1"],
      "cwe": ["CWE-434", "CWE-79"],
      "plainLanguage": "Nothing stops someone uploading a harmful file (like one that runs malicious script when opened) and sharing it as if it were a normal document.",
      "requirement": {
        "title": "Validate and sandbox uploaded files",
        "when": "a file is uploaded",
        "given": "the upload handler receives the file",
        "then": "it validates file type/size against an allow-list, serves files with a content-disposition and content-type that prevent in-browser script execution, and scans for malware"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No link ownership or audit trail for who shared or accessed a file",
      "scenario": "Since viewing requires no login ('without logging in') and the design gives no indication of tracking who created a link or who accessed it, an uploader whose file is leaked cannot prove it, and there is no way to trace misuse back to a link or viewer.",
      "component": "File sharing links epic",
      "likelihood": 2,
      "impact": 2,
      "evidence": [
        { "quote": "Anyone with the link can view the file without logging in." }
      ],
      "asvs": ["V16.5.1"],
      "cwe": ["CWE-778"],
      "plainLanguage": "If a shared file leaks, there's no record of who created the link or who viewed the file to help investigate.",
      "requirement": {
        "title": "Record link creation and access events",
        "given": "a share link is created or used",
        "when": "the event occurs",
        "then": "the system records the owning user, creation time, and access timestamps sufficient to investigate misuse"
      }
    }
  ]
}
